import { Command } from "commander";

import { AppContext, recordCommand } from "../app/context";
import type { CommandDefinition } from "../contract/command-registry";
import { createJsonInputParameters, createObjectInputSchema } from "../contract/metadata";
import { emitError } from "../core/output";
import type { RemoteResult } from "../http/remote-client";
import { loadJsonObjectInput } from "../input/json-input";
import { buildRemoteClient, runRemoteAction } from "./support";

export type JsonInputOptions = {
  data?: string;
  file?: string;
  stdinJson?: boolean;
};

export function addJsonInputOptions(command: Command): Command {
  return command
    .option("--data <json>", "JSON object body")
    .option("--file <path>", "Path to a JSON file or `-` to read from stdin")
    .option("--stdin-json", "Read the JSON object body from stdin");
}

export function buildJsonInputHistory(base: string, options: JsonInputOptions): string {
  if (options.file === "-") {
    return `${base} --file -`;
  }
  if (options.stdinJson) {
    return `${base} --stdin-json`;
  }
  if (options.file) {
    return `${base} --file <path>`;
  }
  if (options.data !== undefined) {
    return `${base} --data <json>`;
  }
  return base;
}

export async function loadJsonBody(
  action: string,
  options: JsonInputOptions
): Promise<Record<string, unknown>> {
  return loadJsonObjectInput({
    data: options.data,
    filePath: options.file,
    stdinJson: options.stdinJson,
    action
  });
}

export async function loadJsonActionBody(
  context: AppContext,
  options: {
    action: string;
    historyCommand: string;
    input: JsonInputOptions;
    validateBody?: (body: Record<string, unknown>) => Record<string, unknown>;
  }
): Promise<Record<string, unknown>> {
  await recordCommand(context, buildJsonInputHistory(options.historyCommand, options.input));

  try {
    const body = await loadJsonBody(options.action, options.input);
    return options.validateBody ? options.validateBody(body) : body;
  } catch (error) {
    emitError({
      jsonOutput: context.jsonMode,
      action: options.action,
      message: error instanceof Error ? error.message : String(error),
      errorType: "invalid_input"
    });
  }
}

export function createJsonRemoteCommand(options: {
  context: AppContext;
  name: string;
  path: string;
  summary: string;
  successMessage: string;
  historyCommand: string;
  examples?: string[];
  notes?: string[];
  inputSchema?: Record<string, unknown>;
  validateBody?: (body: Record<string, unknown>) => Record<string, unknown>;
  run: (
    client: ReturnType<typeof buildRemoteClient>,
    body: Record<string, unknown>
  ) => Promise<RemoteResult<unknown>>;
}): CommandDefinition {
  return {
    name: options.name,
    path: options.path,
    kind: "command",
    summary: options.summary,
    authRequired: true,
    destructive: false,
    confirmationRequired: false,
    examples: options.examples,
    notes: options.notes,
    inputSchema: options.inputSchema ?? createObjectInputSchema(),
    parameters: createJsonInputParameters(),
    build: () =>
      addJsonInputOptions(new Command(options.name).description(options.summary)).action(
        async (input: JsonInputOptions) => {
          const body = await loadJsonActionBody(options.context, {
            action: options.path,
            historyCommand: options.historyCommand,
            input,
            validateBody: options.validateBody
          });

          await runRemoteAction(options.context, {
            action: options.path,
            successMessage: options.successMessage,
            operation: (client) => options.run(client, body)
          });
        }
      )
  };
}
