import { Command } from "commander";

import { AppContext, clearRemoteAuthIfConfigTargetChanged, recordCommand } from "../app/context";
import type { CommandDefinition } from "../contract/command-registry";
import { emitError, emitSuccess } from "../core/output";
import { isConfigKey, parseConfigValue, quoteForHistory } from "../input/validators";

function createConfigShowCommand(context: AppContext): CommandDefinition {
  return {
    name: "show",
    path: "config.show",
    kind: "command",
    summary: "Show persisted remote defaults",
    authRequired: false,
    destructive: false,
    confirmationRequired: false,
    examples: ["pocketbase-cli --json config show"],
    parameters: [],
    build: () =>
      new Command("show")
        .description("Show persisted remote defaults")
        .action(() => {
          emitSuccess({
            jsonOutput: context.jsonMode,
            action: "config.show",
            message: "Current config",
            data: context.state.config
          });
        })
  };
}

function createConfigSetCommand(context: AppContext): CommandDefinition {
  return {
    name: "set",
    path: "config.set",
    kind: "command",
    summary: "Persist remote default value",
    authRequired: false,
    destructive: false,
    confirmationRequired: false,
    parameters: [
      {
        kind: "argument",
        name: "key",
        required: true,
        nargs: 1,
        type: "TEXT",
        help: "Config key to persist: base_url, auth_collection, or timeout"
      },
      {
        kind: "argument",
        name: "value",
        required: true,
        nargs: 1,
        type: "TEXT",
        help: "Config value. Use none, null, or unset to clear the key"
      }
    ],
    examples: [
      "pocketbase-cli --json config set base_url https://pb.example.com",
      "pocketbase-cli --json config set timeout 30"
    ],
    build: () =>
      new Command("set")
        .description("Persist remote default value")
        .argument("<key>")
        .argument("<value>")
        .action(async (key: string, value: string) => {
          if (!isConfigKey(key)) {
            emitError({
              jsonOutput: context.jsonMode,
              action: "config.set",
              message: `Unknown config key: ${key}`
            });
          }

          let parsed: string | number | null;
          try {
            parsed = parseConfigValue(key, value);
          } catch (error) {
            emitError({
              jsonOutput: context.jsonMode,
              action: "config.set",
              message: error instanceof Error ? error.message : String(error)
            });
          }

          const payload = context.state.setConfig(key, parsed);
          const authChange = clearRemoteAuthIfConfigTargetChanged(context);
          await recordCommand(context, `config set ${key} ${quoteForHistory(value)}`);

          emitSuccess({
            jsonOutput: context.jsonMode,
            action: "config.set",
            message: authChange.auth_cleared
              ? "Config updated and saved auth cleared"
              : "Config updated",
            data: {
              ...payload,
              ...authChange
            }
          });
        })
  };
}

function createConfigUnsetCommand(context: AppContext): CommandDefinition {
  return {
    name: "unset",
    path: "config.unset",
    kind: "command",
    summary: "Remove persisted remote default",
    authRequired: false,
    destructive: false,
    confirmationRequired: false,
    parameters: [
      {
        kind: "argument",
        name: "key",
        required: true,
        nargs: 1,
        type: "TEXT",
        help: "Config key to remove: base_url, auth_collection, or timeout"
      }
    ],
    examples: ["pocketbase-cli --json config unset timeout"],
    build: () =>
      new Command("unset")
        .description("Remove persisted remote default")
        .argument("<key>")
        .action(async (key: string) => {
          if (!isConfigKey(key)) {
            emitError({
              jsonOutput: context.jsonMode,
              action: "config.unset",
              message: `Unknown config key: ${key}`
            });
          }

          const payload = context.state.unsetConfig(key);
          const authChange = clearRemoteAuthIfConfigTargetChanged(context);
          await recordCommand(context, `config unset ${key}`);

          emitSuccess({
            jsonOutput: context.jsonMode,
            action: "config.unset",
            message: authChange.auth_cleared
              ? "Config removed and saved auth cleared"
              : "Config removed",
            data: {
              ...payload,
              ...authChange
            }
          });
        })
  };
}

export function createConfigDefinition(context: AppContext): CommandDefinition {
  return {
    name: "config",
    path: "config",
    kind: "group",
    summary: "Persist remote defaults for future commands",
    authRequired: false,
    destructive: false,
    confirmationRequired: false,
    children: [
      createConfigShowCommand(context),
      createConfigSetCommand(context),
      createConfigUnsetCommand(context)
    ],
    build: () => new Command("config").description("Persist remote defaults for future commands")
  };
}
