import type { Command } from "commander";

import type { AppContext } from "../app/context";
import type { CommandParameter } from "../contract/command-registry";
import { createOptionParameter } from "../contract/metadata";
import { requireConfirmation } from "./support";

export const CONFIRMED_COMMAND_METADATA = {
  confirmationRequired: true,
  confirmationFlag: "--yes"
} as const;

export type ConfirmedCommandOptions = {
  yes?: boolean;
};

export function createConfirmationParameter(help: string): CommandParameter {
  return createOptionParameter({
    name: "--yes",
    type: "BOOLEAN",
    help,
    isFlag: true
  });
}

export function addConfirmationOption(command: Command, help: string): Command {
  return command.option("--yes", help);
}

export function requireConfirmedCommand(
  context: AppContext,
  options: {
    action: string;
    yes?: boolean;
    message: string;
    hint: string;
  }
): boolean {
  return requireConfirmation(context, {
    action: options.action,
    yes: Boolean(options.yes),
    message: options.message,
    hint: options.hint
  });
}
