import { Command } from "commander";

import { AppContext, recordCommand } from "../app/context";
import type { CommandDefinition } from "../contract/command-registry";
import {
  addConfirmationOption,
  CONFIRMED_COMMAND_METADATA,
  createConfirmationParameter,
  type ConfirmedCommandOptions,
  requireConfirmedCommand
} from "./confirmed-command";
import { runRemoteAction } from "./support";

export function createCronsDefinition(context: AppContext): CommandDefinition {
  return {
    name: "crons",
    path: "crons",
    kind: "group",
    summary: "Remote cron endpoints",
    authRequired: true,
    destructive: false,
    confirmationRequired: false,
    children: [
      {
        name: "list",
        path: "crons.list",
        kind: "command",
        summary: "List cron jobs",
        authRequired: true,
        destructive: false,
        confirmationRequired: false,
        examples: ["pocketbase-cli --json crons list"],
        build: () =>
          new Command("list")
            .description("List cron jobs")
            .action(async () => {
              await recordCommand(context, "crons list");
              await runRemoteAction(context, {
                action: "crons.list",
                successMessage: "Crons list completed",
                operation: (client) => client.cronsList()
              });
            })
      },
      {
        name: "run",
        path: "crons.run",
        kind: "command",
        summary: "Run a cron job",
        authRequired: true,
        destructive: true,
        ...CONFIRMED_COMMAND_METADATA,
        parameters: [
          {
            kind: "argument",
            name: "job_id",
            required: true,
            nargs: 1,
            type: "TEXT",
            help: "Cron job id to run immediately"
          },
          createConfirmationParameter(
            "Acknowledge that running the cron job can trigger side effects immediately"
          )
        ],
        examples: ["pocketbase-cli --json crons run cleanup --yes"],
        build: (): Command => {
          const command = new Command("run")
            .description("Run a cron job now")
            .argument("<job_id>");

          return addConfirmationOption(
            command,
            "Acknowledge that running a cron job can trigger side effects immediately"
          ).action(async (jobId: string, options: ConfirmedCommandOptions) => {
            requireConfirmedCommand(context, {
              action: "crons.run",
              yes: options.yes,
              message:
                "Cron run can trigger side effects immediately. Re-run with `--yes` to continue.",
              hint:
                "Re-run `crons run <job_id> --yes` after confirming the job should execute now."
            });

            await recordCommand(context, `crons run ${jobId} --yes`);
            await runRemoteAction(context, {
              action: "crons.run",
              successMessage: "Cron run completed",
              operation: (client) => client.cronsRun(jobId)
            });
          });
        }
      }
    ],
    build: () => new Command("crons").description("Remote cron endpoints")
  };
}
